	maxInt := int(^uint(0) >> 1)
	minInt := -maxInt - 1
	for _, event := range events {
		if event.ID == "" || event.Key == "" {
			return nil, false
		}
		if seenEvent, ok := seen[event.ID]; ok {
			if seenEvent != event {
				return nil, false
			}
			continue
		}
		if event.Seq != expected {
			return nil, false
		}
		expected++
		seen[event.ID] = event
		switch event.Kind {
		case "Add":
			current := state[event.Key]
			if event.Delta > 0 && current > maxInt-event.Delta || event.Delta < 0 && current < minInt-event.Delta {
				return nil, false
			}
			state[event.Key] = current + event.Delta
		case "Delete":
			if event.Delta != 0 {
				return nil, false
			}
			delete(state, event.Key)
		default:
			return nil, false
		}
	}
